-- B10 additive DRAFT. Never applied remotely in this task. Native mode stays OFF.

CREATE TABLE IF NOT EXISTS b10_ledger_certifications(
 ledger_id TEXT PRIMARY KEY REFERENCES workers_ai_requests(id) ON DELETE CASCADE,
 raw_neurons REAL NOT NULL CHECK(raw_neurons>=0),
 reserved_units TEXT NOT NULL CHECK(length(reserved_units) BETWEEN 1 AND 19 AND reserved_units NOT GLOB '*[^0-9]*' AND CAST(reserved_units AS INTEGER)>=0 AND CAST(CAST(reserved_units AS INTEGER) AS TEXT)=reserved_units)
);
CREATE VIEW IF NOT EXISTS b10_budget_ledger AS SELECT r.id,r.actor,r.kind,r.request_hash,r.day,r.reserved_neurons,r.status,r.response,r.created_at,c.reserved_units FROM workers_ai_requests r LEFT JOIN b10_ledger_certifications c ON c.ledger_id=r.id AND c.raw_neurons=r.reserved_neurons;
CREATE TRIGGER IF NOT EXISTS b10_invalidate_budget_precision AFTER UPDATE OF reserved_neurons ON workers_ai_requests BEGIN DELETE FROM b10_ledger_certifications WHERE ledger_id=NEW.id; END;

CREATE TABLE IF NOT EXISTS b10_control(id INTEGER PRIMARY KEY CHECK(id=1),active INTEGER NOT NULL DEFAULT 0 CHECK(active IN (0,1)));
INSERT OR IGNORE INTO b10_control VALUES(1,0);
CREATE TABLE IF NOT EXISTS b10_context(id INTEGER PRIMARY KEY CHECK(id=1),purpose TEXT NOT NULL);
CREATE TABLE IF NOT EXISTS b10_guards(id TEXT PRIMARY KEY,ok INTEGER NOT NULL CHECK(ok=1));
CREATE TABLE IF NOT EXISTS b10_deleted_owners(owner_hash TEXT PRIMARY KEY,deleted_at TEXT NOT NULL);
CREATE TABLE IF NOT EXISTS ai_world_heads(owner_id TEXT NOT NULL REFERENCES user_accounts(id) ON DELETE CASCADE,world_id TEXT NOT NULL,head_revision INTEGER NOT NULL CHECK(head_revision>=0),source_hash TEXT NOT NULL,parent_id TEXT,cleanup_generation INTEGER NOT NULL DEFAULT 0,PRIMARY KEY(owner_id,world_id),FOREIGN KEY(owner_id,world_id) REFERENCES user_worlds(owner_id,id) ON DELETE CASCADE);
CREATE TABLE IF NOT EXISTS ai_jobs(id TEXT PRIMARY KEY,owner_id TEXT NOT NULL REFERENCES user_accounts(id) ON DELETE CASCADE,world_id TEXT NOT NULL,operation_id TEXT NOT NULL,request_hash TEXT NOT NULL,contract_version INTEGER NOT NULL,world_revision INTEGER NOT NULL,head_revision INTEGER NOT NULL,source_hash TEXT NOT NULL,parent_id TEXT,target_id TEXT,input TEXT NOT NULL,state TEXT NOT NULL CHECK(state IN ('QUEUED','RUNNING','SUCCEEDED','FAILED','CANCELLED','EXPIRED','RECOVERY_REQUIRED')),provider_phase TEXT NOT NULL DEFAULT 'NOT_DISPATCHED',state_version INTEGER NOT NULL DEFAULT 0,cleanup_generation INTEGER NOT NULL DEFAULT 0,ledger_id TEXT NOT NULL UNIQUE REFERENCES workers_ai_requests(id) ON DELETE CASCADE,budget_day TEXT NOT NULL,result_ref TEXT,created_at TEXT NOT NULL,updated_at TEXT NOT NULL,UNIQUE(owner_id,world_id,operation_id),FOREIGN KEY(owner_id,world_id) REFERENCES user_worlds(owner_id,id) ON DELETE CASCADE);
CREATE INDEX IF NOT EXISTS b10_jobs_owner_world ON ai_jobs(owner_id,world_id,created_at);
CREATE TRIGGER IF NOT EXISTS b10_barrier_user_worlds_insert BEFORE INSERT ON user_worlds WHEN (SELECT active FROM b10_control WHERE id=1)=1 AND NOT EXISTS(SELECT 1 FROM b10_context WHERE id=1) BEGIN SELECT RAISE(ABORT,'native_writer_required'); END;
